    repo = root / "fixture"
    repo.mkdir()
    write(
        repo / "py" / "service.py",
        """
from .helper import helper_value

class OrderService:
    def save_order(self, value):
        with open("orders.txt", "a") as handle:
            handle.write(str(value))
        return helper_value(value)

